INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13081, 'Additive Manufacturing Essentials', 'en', 'Additive Manufacturing Essentials is an introduction to the core principles, technologies, and methods in the field of additive manufacturing. Rooted in industry practice and innovation, the material presents examples and approaches from an array of companies, equipment producers, and software developers. The book is designed to support readers from an array of fields and areas of study, including', 'https://assets.openstax.org/oscms-prodcms/media/documents/additive_manufacturing_web_card.svg', 2025, 4638, 27, 26, 'ox-873', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13082, 'Algebra 1', 'en', 'Algebra 1 is a complete high school algebra curriculum that is 100% aligned with the Texas Essential Knowledge and Skills (TEKS) and the English Language Proficiency Standards (ELPS). OpenStax Algebra 1 is a high-quality instructional material (HQIM) that is flexible enough for core adoption and adaptable enough to support a wide range of teaching strategies and student needs. Algebra 1 is a resea', 'https://assets.openstax.org/oscms-prodcms/media/documents/algebra_1_web_card.svg', 2025, 4639, 27, 26, 'ox-867', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13083, 'Algebra and Trigonometry', 'en', 'Algebra and Trigonometry provides a comprehensive exploration of algebraic principles and meets scope and sequence requirements for a typical introductory algebra and trigonometry course. The modular approach and the richness of content ensure that the book meets the needs of a variety of courses. Algebra and Trigonometry offers a wealth of examples with detailed, conceptual explanations, building', 'https://assets.openstax.org/oscms-prodcms/media/documents/algebra_trigonometry.svg', 2015, 4640, 27, 26, 'ox-38', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13084, 'Algebra and Trigonometry 2e', 'en', 'Algebra and Trigonometry 2e provides a comprehensive exploration of mathematical principles and meets scope and sequence requirements for a typical introductory algebra and trigonometry course. The modular approach and the richness of content ensure that the book addresses the needs of a variety of courses. Algebra and Trigonometry 2e offers a wealth of examples with detailed, conceptual explanati', 'https://assets.openstax.org/oscms-prodcms/media/documents/algebra_trigonometry_2e.svg', 2021, 4641, 27, 26, 'ox-553', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13085, 'American Government', 'en', 'American Government is designed to meet the scope and sequence requirements of the single-semester American government course. This title includes innovative features designed to enhance student learning, including Insider Perspective features and a Get Connected Module that shows students how they can get engaged in the political process. The book provides an important opportunity for students to', 'https://assets.openstax.org/oscms-prodcms/media/documents/american_government.svg', 2016, 4642, 27, 26, 'ox-84', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13086, 'American Government 2e', 'en', 'American Government 2e is designed to meet the scope and sequence requirements of the single-semester American Government course. This title includes innovative features designed to enhance student learning, including Insider Perspective features and a Get Connected module that shows students how they can get engaged in the political process. The book provides an important opportunity for students', 'https://assets.openstax.org/oscms-prodcms/media/documents/american_government_2e_book_card.svg', 2019, 4642, 27, 26, 'ox-300', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13087, 'American Government 3e', 'en', 'American Government 3e aligns with the topics and objectives of many government courses. Faculty involved in the project have endeavored to make government workings, issues, debates, and impacts meaningful and memorable to students while maintaining the conceptual coverage and rigor inherent in the subject. With this objective in mind, the content of this textbook has been developed and arranged t', 'https://assets.openstax.org/oscms-prodcms/media/documents/american_government_3e_web_card.svg', 2021, 4643, 27, 26, 'ox-518', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13088, 'American Government 4e', 'en', 'American Government 4e aligns with the topics and objectives of many government courses. The authors have worked to develop meaningful and memorable explanations, narratives, and examples regarding the actions, workings, and outputs of government. The offering focuses on the real-world impact of government, and presents the importance and benefits of civic engagement by students. This book follows', 'https://assets.openstax.org/oscms-prodcms/media/documents/american_government_4e_web_card.svg', 2025, 4643, 27, 26, 'ox-931', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13089, 'Anatomy and Physiology', 'en', 'Anatomy and Physiology is a dynamic textbook for the two-semester human anatomy and physiology course for life science and allied health majors. The book is organized by body system and covers standard scope and sequence requirements. Its lucid text, strategically constructed art, career features, and links to external learning tools address the critical teaching and learning challenges in the cou', 'https://assets.openstax.org/oscms-prodcms/media/documents/anatomy_physiology.svg', 2013, 4644, 27, 26, 'ox-35', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13090, 'Anatomy and Physiology 2e', 'en', 'Anatomy and Physiology 2e is developed to meet the scope and sequence for a two-semester human anatomy and physiology course for life science and allied health majors. The book is organized by body systems. The revision focuses on inclusive and equitable instruction and includes new student support. Illustrations have been extensively revised to be clearer and more inclusive. The web-based version', 'https://assets.openstax.org/oscms-prodcms/media/documents/anatomy_and_physiology_2e_webcard.svg', 2022, 4645, 27, 26, 'ox-585', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13091, 'The AP Physics Collection', 'en', 'The AP Physics Collection is a free, turnkey solution for your AP ® Physics course, brought to you through a collaboration between OpenStax and Rice Online Learning. The integrated collection features the OpenStax College Physics for AP ® Courses text, Concept Trailer videos, instructional videos, problem solution videos, and a correlation guide to help you align all of your free content. The Coll', 'https://assets.openstax.org/oscms-prodcms/media/documents/college_physics_for_ap_course_book_card.svg', 2015, 4646, 27, 26, 'ox-47', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13092, 'Astronomy', 'en', 'Astronomy is designed to meet the scope and sequence requirements of one- or two-semester introductory astronomy courses. The book begins with relevant scientific fundamentals and progresses through an exploration of the solar system, stars, galaxies, and cosmology. The Astronomy textbook builds student understanding through the use of relevant analogies, clear and non-technical explanations, and', 'https://assets.openstax.org/oscms-prodcms/media/documents/astronomy.svg', 2016, 4647, 27, 26, 'ox-81', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13093, 'Astronomy 2e', 'en', 'Designed to meet the scope and sequence of your course, Astronomy 2e is written in clear non-technical language, with the occasional touch of humor and a wide range of clarifying illustrations. It has many analogies drawn from everyday life to help non-science majors appreciate, on their own terms, what our modern exploration of the universe is revealing. The book can be used for either a one-seme', 'https://assets.openstax.org/oscms-prodcms/media/documents/astronomy_2e_webcard.svg', 2022, 4648, 27, 26, 'ox-576', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13094, 'Biology', 'en', 'Biology is designed to cover the scope and sequence requirements of a typical two-semester biology course for science majors. The text provides comprehensive coverage of foundational research and core biology concepts through an evolutionary lens. Biology includes rich features that engage students in scientific inquiry, highlight careers in the biological sciences, and offer everyday applications', 'https://assets.openstax.org/oscms-prodcms/media/documents/biology.svg', 2016, 4649, 27, 26, 'ox-121', 'cc-by', 0, NULL);
