INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13118, 'Concepts of Biology', 'en', 'Concepts of Biology is designed for the typical introductory biology course for nonmajors, covering standard scope and sequence requirements. The text includes interesting applications and conveys the major themes of biology, with content that is meaningful and easy to understand. The book is designed to demonstrate biology concepts and to promote scientific literacy.', 'https://assets.openstax.org/oscms-prodcms/media/documents/concpets_biology_eZrc8yQ.svg', 2013, 4669, 27, 26, 'ox-34', 'cc-by', 0, NULL);
