INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13133, 'Introduction to Business 2e', 'en', 'Introduction to Business 2e provides a strong, multidimensional foundation in the concepts, skills, and real-world examples of contemporary business. Welcoming and relevant narratives support students as they engage in core themes such as decision making, ethics, customer satisfaction, entrepreneurship, global business, and managing technological and societal changes. The material includes hundred', 'https://assets.openstax.org/oscms-prodcms/media/documents/introduction_to_business_2e_web_card.svg', 2026, 4683, 27, 26, 'ox-960', 'cc-by', 0, NULL);
