INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13136, 'Introduction to Philosophy', 'en', 'Designed to meet the scope and sequence of your course, Introduction to Philosophy surveys logic, metaphysics, epistemology, theories of value, and history of philosophy thematically. To provide a strong foundation in global philosophical discourse, diverse primary sources and examples are central to the design, and the text emphasizes engaged reading, critical thinking, research, and analytical s', 'https://assets.openstax.org/oscms-prodcms/media/documents/introduction_to_philosophy_webcard.svg', 2022, 4686, 27, 26, 'ox-601', 'cc-by', 0, NULL);
