INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13141, 'Introduction to Sociology 3e', 'en', 'Introduction to Sociology 3e aligns to the topics and objectives of many introductory sociology courses. It is arranged in a manner that provides foundational sociological theories and contexts, then progresses through various aspects of human and societal interactions. The new edition is focused on driving meaningful and memorable learning experiences related to critical thinking about society an', 'https://assets.openstax.org/oscms-prodcms/media/documents/introduction_to_sociology_3e_web_card.svg', 2021, 4691, 27, 26, 'ox-515', 'cc-by', 0, NULL);
