INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13144, 'Introductory Statistics', 'en', 'Introductory Statistics follows scope and sequence requirements of a one-semester introduction to statistics course and is geared toward students majoring in fields other than math or engineering. The text assumes some knowledge of intermediate algebra and focuses on statistics application over theory. Introductory Statistics includes innovative practical applications that make the text relevant a', 'https://assets.openstax.org/oscms-prodcms/media/documents/statistics.svg', 2013, 4694, 27, 26, 'ox-36', 'cc-by', 0, NULL);
