INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13156, 'Organizational Behavior', 'en', 'This OpenStax resource aligns to introductory courses in Organizational Behavior. The text presents the theory, concepts, and applications with particular emphasis on the impact that individuals and groups can have on organizational performance and culture. An array of recurring features engages students in entrepreneurial thinking, managing change, using tools/technology, and responsible manageme', 'https://assets.openstax.org/oscms-prodcms/media/documents/organizational_behavior_book_card.svg', 2019, 4706, 27, 26, 'ox-315', 'cc-by', 0, NULL);
