INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13158, 'Physics', 'en', 'This Physics resource was developed under the guidance and support of experienced high school teachers and subject matter experts. It is presented here in multiple formats: PDF, online, and low-cost print. Beginning with an introduction to physics and scientific processes and followed by chapters focused on motion, mechanics, thermodynamics, waves, and light, this book incorporates a variety of to', 'https://assets.openstax.org/oscms-prodcms/media/documents/high_school_physics_web_card.svg', 2020, 4708, 27, 26, 'ox-415', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13159, 'Population Health for Nurses', 'en', 'Population Health for Nurses prepares nurses to develop interventions, policies, and practices that promote health equity and improved health outcomes across the health care delivery continuum. The text emphasizes the social determinants of health and how nurses can plan and implement health promotion and disease prevention interventions. It takes a holistic perspective, connecting human health be', 'https://assets.openstax.org/oscms-prodcms/media/documents/population_health_for_nurses_web_card.svg', 2024, 4709, 27, 26, 'ox-772', 'cc-by', 0, NULL);
