INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13178, 'Principles of Management', 'en', 'Principles of Management is designed to meet the scope and sequence requirements of the introductory course on management. This is a traditional approach to management using the leading, planning, organizing, and controlling approach. Management is a broad business discipline, and the Principles of Management course covers many management areas such as human resource management and strategic manag', 'https://assets.openstax.org/oscms-prodcms/media/documents/principles_of_management_book_card.svg', 2019, 4722, 27, 26, 'ox-304', 'cc-by', 0, NULL);
