INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13207, 'Precálculo 2ed', 'en', 'Precálculo 2ed es adaptable y está diseñado para satisfacer las necesidades de diversos cursos de precálculo. Es un texto integral que abarca más temas que un curso típico de precálculo de un semestre. El contenido está organizado por objetivos de aprendizaje claramente definidos e incluye ejemplos prácticos que demuestran enfoques de resolución de problemas de una forma accesible. Si se encuentra', 'https://assets.openstax.org/oscms-prodcms/media/documents/precalculo_2ed_WebCard_oFhHBTC.svg', 2022, 4744, 27, 26, 'ox-597', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13208, 'Química 2ed', 'en', 'Química 2ed está diseñado para cumplir con los requisitos de alcance y secuencia del curso de química general de dos semestres. Este libro de texto brinda una gran oportunidad para que los estudiantes aprendan los conceptos básicos de la química y comprendan cómo se aplican a sus vidas y al mundo que los rodea. El libro incluye una serie de características innovadoras, como ejercicios interactivos', 'https://assets.openstax.org/oscms-prodcms/media/documents/quimica_2ed_webcard.svg', 2022, 4745, 27, 26, 'ox-599', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (13209, 'Química: Comenzando con los átomos 2ed', 'en', 'Química: Comenzando con los átomos 2ed es un libro de texto introductorio, revisado por colegas y con licencia abierta. Es el producto de la alianza editorial entre OpenStax, la Universidad de Connecticut y su Federación de Centros de Estudiantes. Este libro es la adaptación de Química: Comenzando con los átomos 2ed de OpenStax. La intención de "comenzando con los átomos" implica algunos principio', 'https://assets.openstax.org/oscms-prodcms/media/documents/quimica_comenzando_con_los_atomos_2ed_webcard.svg', 2022, 4746, 27, 26, 'ox-600', 'cc-by', 0, NULL);
